def stays_inside(path: str) -> bool:
    """True when path is relative and, after resolving "." and ".." segments, never climbs above its starting directory."""
    ex stays_inside("a.txt") == True
    ex stays_inside("sub/../a.txt") == True
    ex stays_inside("..") == False
    ex stays_inside("/etc/passwd") == False
    ex stays_inside("sub/../../x") == False
    p = path.replace("\\", "/")
    if p.startswith("/"):
        return False
    depth = 0
    for seg in p.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            depth -= 1
            if depth < 0:
                return False
        else:
            depth += 1
    return True

def read_public(path: str) -> str uses fs:
    """Text of the file at request path `path` inside the directory `notes`, or "" when the path leaves `notes`, or the file is missing or unreadable. Reads through `fs` confined to `notes` with `fs.sub`."""
    post stays_inside(path) or out == ""
    if not stays_inside(path):
        return ""
    with fs = fs.sub("notes"):
        return fs.read_text(path) else ""
